//! The PHP pool for real (F5.3): official `php-cgi.exe` workers supervised by `Service` over
//! Job Objects, and the Nginx generated by `crisol-core::nginx` in front of them.
//!
//! Needs `php-7.4.33-nts-Win32-vc15-x64.zip` and `nginx-1.28.3.zip` in
//! `CRISOL_TEST_DOWNLOADS`. Everything runs from a temporary home on ports 19080 and
//! 19100-19101, and is stopped at the end.
//!
//! ```text
//! CRISOL_TEST_DOWNLOADS=<folder> cargo test -p crisol-platform --test php_pool -- --ignored --nocapture
//! ```

// Test code: a failed `unwrap` is the failure report.
#![allow(clippy::unwrap_used)]
#![cfg(windows)]

use std::collections::BTreeSet;
use std::fs;
use std::io::{Read, Write};
use std::net::TcpStream;
use std::path::{Path, PathBuf};
use std::process::Command;
use std::sync::Arc;
use std::time::{Duration, Instant};

use crisol_core::catalog::Catalog;
use crisol_core::config::PhpConfig;
use crisol_core::fetch::fake::FakeFetcher;
use crisol_core::install::{install, InstallOptions};
use crisol_core::nginx::{write_nginx_config, NginxInput, NginxSite, PhpPools};
use crisol_core::paths::CrisolPaths;
use crisol_core::phpini::{write_php_ini, PhpIniSettings};
use crisol_core::phppool::pool_spec;
use crisol_core::service::{Service, ServiceEvent, ServiceState};
use crisol_core::sites::{DocRoot, Site, SiteKind};
use crisol_platform::{JobObjectSupervisor, WindowsPortProbe};

const HTTP: u16 = 19080;
const PORTS: [u16; 2] = [19100, 19101];
const VERSION: &str = "7.4.33";

fn install_from_downloads(paths: &CrisolPaths, service: &str, version: &str) -> PathBuf {
    let folder = PathBuf::from(std::env::var_os("CRISOL_TEST_DOWNLOADS").expect("set it"));
    let catalog = Catalog::embedded().unwrap();
    let package = catalog
        .packages()
        .iter()
        .find(|p| p.service == service && p.version.to_string() == version)
        .unwrap();
    let fetcher = FakeFetcher::new();
    let file = folder.join(package.url.rsplit('/').next().unwrap());
    fetcher.serve(&package.url, fs::read(file).unwrap());
    install(
        package,
        paths,
        &fetcher,
        &InstallOptions::default(),
        &mut |_| {},
    )
    .unwrap()
    .path
}

fn get(path: &str) -> String {
    let mut stream = TcpStream::connect(("127.0.0.1", HTTP)).unwrap();
    stream
        .set_read_timeout(Some(Duration::from_secs(10)))
        .unwrap();
    write!(
        stream,
        "GET {path} HTTP/1.1\r\nHost: docs.test\r\nConnection: close\r\n\r\n"
    )
    .unwrap();
    let mut body = String::new();
    let _ = stream.read_to_string(&mut body);
    body
}

fn nginx(dir: &Path, main: &Path, args: &[&str]) -> std::process::Output {
    Command::new(dir.join("nginx.exe"))
        .arg("-c")
        .arg(main)
        .arg("-p")
        .arg(dir)
        .args(args)
        .output()
        .unwrap()
}

#[test]
#[ignore = "needs CRISOL_TEST_DOWNLOADS with the official PHP 7.4 and Nginx archives (Windows)"]
#[allow(clippy::too_many_lines)]
fn real_workers_are_recycled_behind_nginx_and_the_pool_stays_running() {
    let tmp = tempfile::TempDir::new().unwrap();
    let paths = CrisolPaths::new(tmp.path().join("home")).unwrap();
    let php_dir = install_from_downloads(&paths, "php", VERSION);
    let nginx_dir = install_from_downloads(&paths, "nginx", "1.28.3");
    write_php_ini(&paths, VERSION, &PhpIniSettings::default()).unwrap();

    // A site whose script says which worker answered.
    let root = paths.home().join("www").join("docs");
    fs::create_dir_all(&root).unwrap();
    fs::write(
        root.join("v.php"),
        "<?php echo 'PHP ', PHP_VERSION, ' pid ', getmypid();",
    )
    .unwrap();
    let site = Site {
        name: "docs".to_owned(),
        domain: "docs.test".to_owned(),
        root: root.clone(),
        docroot: root,
        docroot_rule: DocRoot::Root,
        kind: SiteKind::Parked,
        secure: false,
    };
    let pools = PhpPools::default().with(VERSION, &PORTS);
    let sites = [NginxSite {
        site: &site,
        php: Some(VERSION),
    }];
    let written = write_nginx_config(&NginxInput {
        paths: &paths,
        nginx_dir: &nginx_dir,
        http_port: HTTP,
        tls: None,
        sites: &sites,
        pools: &pools,
    })
    .unwrap();
    let test = nginx(&nginx_dir, &written.main, &["-t"]);
    assert!(
        test.status.success(),
        "{}",
        String::from_utf8_lossy(&test.stderr)
    );

    // The pool: two workers that recycle after every 2 requests.
    let config = PhpConfig {
        max_requests: 2,
        ..PhpConfig::default()
    };
    let spec = pool_spec(&paths, &config, VERSION, &php_dir, &PORTS).unwrap();
    let mut pool = Service::new(
        spec,
        Arc::new(JobObjectSupervisor::new()),
        Arc::new(WindowsPortProbe::new()),
    );
    let mut events: Vec<ServiceEvent> = Vec::new();
    events.extend(pool.start(Instant::now()).unwrap());
    let deadline = Instant::now() + Duration::from_secs(20);
    while *pool.state() != ServiceState::Running {
        assert!(
            Instant::now() < deadline && !matches!(pool.state(), ServiceState::Failed(_)),
            "the pool did not come up: {:?}",
            pool.state()
        );
        std::thread::sleep(Duration::from_millis(150));
        events.extend(pool.tick(Instant::now()));
    }

    let mut running = Command::new(nginx_dir.join("nginx.exe"))
        .arg("-c")
        .arg(&written.main)
        .arg("-p")
        .arg(&nginx_dir)
        .spawn()
        .unwrap();
    assert!(
        (0..50).any(|_| {
            std::thread::sleep(Duration::from_millis(100));
            TcpStream::connect(("127.0.0.1", HTTP)).is_ok()
        }),
        "nginx did not listen"
    );

    // Twelve requests through Nginx: each is served by PHP 7.4.33, and because every worker
    // quits after two, several different processes answer while the pool never leaves Running.
    let mut pids = BTreeSet::new();
    let mut failures = Vec::new();
    for round in 0..12 {
        let answer = get("/v.php");
        if answer.starts_with("HTTP/1.1 200") && answer.contains("PHP 7.4.33 pid ") {
            let pid = answer.rsplit("pid ").next().unwrap().trim().to_owned();
            pids.insert(pid);
        } else {
            failures.push((round, answer));
        }
        for _ in 0..3 {
            std::thread::sleep(Duration::from_millis(100));
            events.extend(pool.tick(Instant::now()));
        }
        assert_eq!(*pool.state(), ServiceState::Running, "round {round}");
    }

    // The same script by the names Windows treats as the same file: it runs, it is never
    // sent as text.
    let aliases: Vec<(&str, String)> = ["/v.PHP", "/v.Php", "/v.php.", "/v.php%20"]
        .into_iter()
        .map(|path| (path, get(path)))
        .collect();

    // Stop everything before judging, so a failed assertion leaves nothing running.
    let _ = nginx(&nginx_dir, &written.main, &["-s", "stop"]);
    let _ = running.wait();
    let stopped_events = pool.stop(Instant::now());
    events.extend(stopped_events);
    let deadline = Instant::now() + Duration::from_secs(10);
    while *pool.state() != ServiceState::Stopped && Instant::now() < deadline {
        std::thread::sleep(Duration::from_millis(100));
        events.extend(pool.tick(Instant::now()));
    }

    assert_eq!(*pool.state(), ServiceState::Stopped);
    assert!(failures.is_empty(), "requests that failed: {failures:?}");
    for (path, answer) in &aliases {
        assert!(
            answer.contains("PHP 7.4.33 pid ") && !answer.contains("<?php"),
            "{path}: {answer}"
        );
    }
    assert!(
        pids.len() >= 3,
        "workers should have been recycled, saw pids {pids:?}"
    );
    assert!(
        !events
            .iter()
            .any(|e| matches!(e, ServiceEvent::WorkerCrashed { .. })),
        "a recycle is not a crash: {events:?}"
    );
    eprintln!("12 requests answered by {} different workers", pids.len());
}
